ControlPropertyState.AutoRuleBindingString:
Refresh('arcade.preventivo');
UpdateContext({ locApprovaOk: true });
With({ p: LookUp('arcade.preventivo', id_preventivo = galApprovazioni.Selected.id_preventivo) },
  // il preventivo nel frattempo è cambiato (rimandato, già approvato)?
  If(p.stato <> "in_approvazione",
    UpdateContext({ locApprovaOk: false });
    RemoveIf(colInApprovazione, id_preventivo = p.id_preventivo);
    Notify("Il preventivo non è più in approvazione", NotificationType.Warning),

    IfError(
      Patch('arcade.preventivo', p, {
          stato: "inviato",
          approvato_da: gblUtente.id_utente,
          approvato_il: Now(),
          inviato_il: Now(),
          valido_fino: DateAdd(Today(), GiorniValidita, TimeUnit.Days) }),

      UpdateContext({ locApprovaOk: false });
      Notify("Approvazione non riuscita: " & FirstError.Message, NotificationType.Error)
    )
  );
  // esito: solo se l'approvazione è riuscita tolgo dall'elenco, avviso e torno agli stand
  If(locApprovaOk,
    RemoveIf(colInApprovazione, id_preventivo = p.id_preventivo);
    Notify("Preventivo n. " & p.id_preventivo & " approvato e inviato", NotificationType.Success);
    Navigate(scrStand, ScreenTransition.Fade)
  )
)

UpdateContext({ locRimandaOk: true });
With({ p: LookUp('arcade.preventivo', id_preventivo = galApprovazioni.Selected.id_preventivo) },
  IfError(
    Patch('arcade.preventivo', p, { stato: "bozza" }),

    UpdateContext({ locRimandaOk: false });
    Notify("Operazione non riuscita: " & FirstError.Message, NotificationType.Error)
  );
  // esito: solo se il rimando è riuscito tolgo dall'elenco, avviso e torno agli stand
  If(locRimandaOk,
    RemoveIf(colInApprovazione, id_preventivo = p.id_preventivo);
    Notify("Preventivo n. " & p.id_preventivo & " rimandato in bozza: lo stand torna libero",
           NotificationType.Information);
    Navigate(scrStand, ScreenTransition.Fade)
  )
)
